use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let year = input.as_i64().unwrap();
    if year < 1 || year > 9999 {
        return Value::Null;
    }
    if year % 4 == 0 && (year % 100 != 0 || year % 400 == 0) {
        Value::Bool(true)
    } else {
        Value::Bool(false)
    }
}
